117	func TestApprovalStartsTimerAtApprovalNotSubmission(t *testing.T) {
118		w, c := setupTimeout(t, 30*time.Second)
119		// 改造为开启审批的超时策略。
120		p := timeoutPolicy(c, 30*time.Second)
121		p.ID = "p-approval-timeout"
122		p.ApprovalThreshold = 10
123		p.ApprovalWait = time.Hour
124		if err := w.SavePolicy(p); err != nil {
125			t.Fatal(err)
126		}
127		if _, err := w.CreateSession("sa", "payer", "dev-approve", c.t.Add(2*time.Hour)); err != nil {
128			t.Fatal(err)
129		}
130	
131		in := timeoutApply()
132		in.PolicyID = "p-approval-timeout"
133		pending, err := w.Apply(in)
134		if err != nil {
135			t.Fatal(err)
136		}
137		if pending.State != RequestPendingApproval {
138			t.Fatalf("state = %v", pending.State)
139		}
140		// 待审批期间不预留，所有预留计时字段为空。
141		if !pending.ReservedAt.IsZero() || pending.ReserveDuration != 0 ||
142			!pending.ReserveDeadline.IsZero() || !pending.ReserveExpiredAt.IsZero() {
143			t.Fatalf("pending request must carry no reserve timing: %+v", pending)
144		}
145	
146		// 等待审批耗时 20 秒（不计入预留时长）。
147		c.t = c.t.Add(20 * time.Second)
148		approved, err := w.Approve("u1", "r1", "sa", "dev-approve")
149		if err != nil {
150			t.Fatal(err)
151		}
152		if !approved.ReservedAt.Equal(c.t) {
153			t.Fatalf("reservedAt = %v, want approval time %v", approved.ReservedAt, c.t)
154		}
155		wantDeadline := c.t.Add(30 * time.Second) // 自批准成功起算，而非提交时刻 + 30s
156		if !approved.ReserveDeadline.Equal(wantDeadline) {
157			t.Fatalf("deadline = %v, want %v (approval wait must not count)", approved.ReserveDeadline, wantDeadline)
158		}
159		if !approved.ReserveExpiredAt.IsZero() {
160			t.Fatalf("release time right after approval = %v, want zero", approved.ReserveExpiredAt)
161		}
162	
163		// 提交后 45 秒（若从提交起算早已超时）、批准后 25 秒：仍在预留中。
164		c.t = c.t.Add(25 * time.Second)
165		if req, _ := w.Request("u1", "r1"); req.State != RequestReserved {
166			t.Fatalf("state = %v, want still reserved before approval-based deadline", req.State)
167		}
168		// 批准后 30 秒：超时。
169		c.t = c.t.Add(5 * time.Second)
170		req, _ := w.Request("u1", "r1")
171		if req.State != RequestReservationExpired {
172			t.Fatalf("state = %v, want reservation expired", req.State)
173		}
174		if !req.ReserveExpiredAt.Equal(wantDeadline) {
175			t.Fatalf("release time = %v, want deadline %v", req.ReserveExpiredAt, wantDeadline)
176		}
177	}
