179	func TestFailedApprovalDoesNotStartTimer(t *testing.T) {
180		w, c := setupTimeout(t, 30*time.Second)
181		// 一条关闭超时的策略，用门槛内的直接预留压占出资账户余额。
182		fill := validPolicy(c)
183		fill.ID = "p-fill"
184		fill.MaxTotal = 1000
185		if err := w.SavePolicy(fill); err != nil {
186			t.Fatal(err)
187		}
188		// 开启审批的超时策略：等待期限 3 小时，预留超时 30 秒，累计额度放宽。
189		p := timeoutPolicy(c, 30*time.Second)
190		p.ID = "p-approval-timeout"
191		p.MaxTotal = 1000
192		p.ApprovalThreshold = 10
193		p.ApprovalWait = 3 * time.Hour
194		if err := w.SavePolicy(p); err != nil {
195			t.Fatal(err)
196		}
197		if _, err := w.CreateSession("sa", "payer", "dev-approve", c.t.Add(4*time.Hour)); err != nil {
198			t.Fatal(err)
199		}
200	
201		in := timeoutApply()
202		in.PolicyID = "p-approval-timeout"
203		in.RequestID = "big"
204		if _, err := w.Apply(in); err != nil {
205			t.Fatal(err)
206		}
207		// 再用九笔费用恰好等于门槛的直接预留各 10（在不超时的 p-fill 下），
208		// 把可用余额压到 10（< 待审批费用 20）。
209		for i := 0; i < 9; i++ {
210			drop := baseApply()
211			drop.PolicyID = "p-fill"
212			drop.RequestID = fmt.Sprintf("drop%d", i)
213			drop.EstimatedFee = 10
214			if _, err := w.Apply(drop); err != nil {
215				t.Fatal(err)
216			}
217		}
218		// 批准时余额不足：失败且不能提前开始预留计时。
219		if _, err := w.Approve("u1", "big", "sa", "dev-approve"); !errors.Is(err, ErrInsufficientBalance) {
220			t.Fatalf("approve err = %v, want ErrInsufficientBalance", err)
221		}
222	
223		// 即使越过“提交时刻 + 30 秒”，请求仍在待审批，没有任何预留计时信息。
224		c.t = c.t.Add(40 * time.Second)
225		req, _ := w.Request("u1", "big")
226		if req.State != RequestPendingApproval {
227			t.Fatalf("state = %v, want still pending", req.State)
228		}
229		if !req.ReservedAt.IsZero() || !req.ReserveDeadline.IsZero() || !req.ReserveExpiredAt.IsZero() {
230			t.Fatalf("failed approval must not start timer: %+v", req)
231		}
232	
233		// 释放一笔直接预留后，批准成功；截止时刻自批准成功时刻起算（t+40s+30s）。
234		if _, err := w.Cancel("u1", "drop0"); err != nil {
235			t.Fatal(err)
236		}
237		approved, err := w.Approve("u1", "big", "sa", "dev-approve")
238		if err != nil {
239			t.Fatal(err)
240		}
241		wantDeadline := c.t.Add(30 * time.Second)
242		if !approved.ReservedAt.Equal(c.t) || !approved.ReserveDeadline.Equal(wantDeadline) {
243			t.Fatalf("timing = %+v, want reservedAt %v deadline %v", approved, c.t, wantDeadline)
244		}
245		c.t = wantDeadline
246		r, _ := w.Request("u1", "big")
247		if r.State != RequestReservationExpired || !r.ReserveExpiredAt.Equal(wantDeadline) {
248			t.Fatalf("final request = %+v, want timeout at %v", r, wantDeadline)
249		}
250	}
