252	func TestReservationTimeoutReleasesOnEveryQuery(t *testing.T) {
253		for _, trigger := range []string{"Request", "Balance", "Account", "Policy", "Ledger", "AccountLedger"} {
254			t.Run(trigger, func(t *testing.T) {
255				w, c := setupTimeout(t, 30*time.Second)
256				if _, err := w.Apply(timeoutApply()); err != nil {
257					t.Fatal(err)
258				}
259				// 超过截止时刻很久才访问：释放时间仍必须是截止时刻。
260				c.t = c.t.Add(10 * time.Minute)
261	
262				switch trigger {
263				case "Request":
264					if req, err := w.Request("u1", "r1"); err != nil || req.State != RequestReservationExpired {
265						t.Fatalf("Request: %+v %v", req, err)
266					}
267				case "Balance":
268					if bal, err := w.Balance("payer"); err != nil || bal != (Balances{Available: 100, Reserved: 0}) {
269						t.Fatalf("Balance = %+v %v", bal, err)
270					}
271				case "Account":
272					if acc, err := w.Account("payer"); err != nil || acc.Balances != (Balances{Available: 100, Reserved: 0}) {
273						t.Fatalf("Account = %+v %v", acc, err)
274					}
275				case "Policy":
276					if pv, err := w.Policy("p-timeout"); err != nil || pv.ReservedTotal != 0 {
277						t.Fatalf("Policy reserved = %d %v", pv.ReservedTotal, err)
278					}
279				case "Ledger":
280					if n := countKind(w.Ledger(), LedgerReservationExpiration); n != 1 {
281						t.Fatalf("timeout entries = %d, want 1", n)
282					}
283				case "AccountLedger":
284					if n := countKind(w.AccountLedger("payer"), LedgerRefund); n != 1 {
285						t.Fatalf("refund entries = %d, want 1", n)
286					}
287				}
288	
289				// 无论从哪个入口触发，请求都已转为超时终态，资金全部释放。
290				req, _ := w.Request("u1", "r1")
291				if req.State != RequestReservationExpired {
292					t.Fatalf("state = %v, want reservation expired", req.State)
293				}
294				if !req.ReserveExpiredAt.Equal(req.ReserveDeadline) {
295					t.Fatalf("release time %v must equal deadline %v, not access time", req.ReserveExpiredAt, req.ReserveDeadline)
296				}
297				if req.ActualFee != 0 {
298					t.Fatalf("actual fee = %d, want 0", req.ActualFee)
299				}
300				if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
301					t.Fatalf("balance = %+v, want {100 0}", bal)
302				}
303				pv, _ := w.Policy("p-timeout")
304				if pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
305					t.Fatalf("totals = reserved %d spent %d, want 0/0", pv.ReservedTotal, pv.SpentTotal)
306				}
307			})
308		}
309	}
