606	func TestSessionPolicyLifecycleDoesNotShortenDeadline(t *testing.T) {
607		w, c := newTestWallet()
608		mustAccount(t, w, "payer", 100)
609		mustAccount(t, w, "u1", 0)
610		mustAccount(t, w, "u2", 0)
611		// 申请会话仅 2 分钟有效；策略窗口长达 4 小时、预留超时 1 小时。
612		if _, err := w.CreateSession("s1", "u1", "dev1", c.t.Add(2*time.Minute)); err != nil {
613			t.Fatal(err)
614		}
615		if _, err := w.CreateSession("sa", "payer", "dev-approve", c.t.Add(4*time.Hour)); err != nil {
616			t.Fatal(err)
617		}
618		p := validPolicy(c)
619		p.ID = "p-long"
620		p.EndsAt = c.t.Add(4 * time.Hour)
621		p.MaxReserveDuration = time.Hour
622		if err := w.SavePolicy(p); err != nil {
623			t.Fatal(err)
624		}
625		in := baseApply()
626		in.PolicyID = "p-long"
627		if _, err := w.Apply(in); err != nil {
628			t.Fatal(err)
629		}
630		deadline := c.t.Add(time.Hour)
631	
632		// 申请会话在 2 分钟后到期且被吊销：已预留请求不受影响，截止时间不变。
633		c.t = c.t.Add(90 * time.Second)
634		if err := w.RevokeSession("s1"); err != nil {
635			t.Fatal(err)
636		}
637		req, _ := w.Request("u1", "r1")
638		if req.State != RequestReserved {
639			t.Fatalf("session expiry/revoke must not release reservation: %v", req.State)
640		}
641	
642		// 越过出资账户会话到期等事件，直到截止时刻之后：进入超时终态，
643		// 释放时间仍是原截止时刻，而非很久之后的访问时刻。
644		c.t = c.t.Add(90 * time.Minute)
645		req, _ = w.Request("u1", "r1")
646		if req.State != RequestReservationExpired {
647			t.Fatalf("state = %v, want timeout (not released early)", req.State)
648		}
649		if !req.ReserveDeadline.Equal(deadline) || !req.ReserveExpiredAt.Equal(deadline) {
650			t.Fatalf("deadline moved: deadline %v release %v, want %v", req.ReserveDeadline, req.ReserveExpiredAt, deadline)
651		}
652	
653		// 停用策略不提前缩短未到期预留：构造第二笔，在截止前停用，仍需等到截止时刻。
654		w2, c2 := setupTimeout(t, time.Hour)
655		if _, err := w2.CreateSession("sa", "payer", "dev-approve", c2.t.Add(3*time.Hour)); err != nil {
656			t.Fatal(err)
657		}
658		in2 := timeoutApply()
659		in2.RequestID = "r2"
660		if _, err := w2.Apply(in2); err != nil {
661			t.Fatal(err)
662		}
663		deadline2 := c2.t.Add(time.Hour)
664		c2.t = c2.t.Add(30 * time.Minute)
665		if _, err := w2.DeactivatePolicy("p-timeout", "sa", "dev-approve", "stop"); err != nil {
666			t.Fatal(err)
667		}
668		if r, _ := w2.Request("u1", "r2"); r.State != RequestReserved {
669			t.Fatalf("deactivation must not expire reservation early: %v", r.State)
670		}
671		c2.t = deadline2 // 到达原截止时刻
672		r, _ := w2.Request("u1", "r2")
673		if r.State != RequestReservationExpired {
674			t.Fatalf("state at original deadline = %v, want reservation expired", r.State)
675		}
676		if !r.ReserveExpiredAt.Equal(deadline2) {
677			t.Fatalf("release time = %v, want original deadline %v", r.ReserveExpiredAt, deadline2)
678		}
679		// 超时退款而非停用拒绝。
680		if r.RejectReason != "" {
681			t.Fatalf("timeout request must not carry reject reason: %q", r.RejectReason)
682		}
683		if countKind(w2.Ledger(), LedgerRejection) != 0 {
684			t.Fatal("reservation timeout must not be recorded as rejection")
685		}
686	}
